import {MANDATES} from './representation-catalog.js?v=4.0.0';
import {orderedOffers,PREFERENCES,offerComparison} from './career-plan.js?v=4.0.0';
import {leagueDef} from './leagues.js?v=4.0.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const outcome=x=>({accepted:'Accord',compromise:'Compromis',refused:'Refus'})[x]||x;
const money=n=>Number.isFinite(n)?n.toLocaleString('fr-FR',{maximumFractionDigits:2})+' €':'—';
const button=(text,action,disabled=false)=>`<button class="secondary" id="contract-action-${esc(action.replace(':','-'))}" data-action="${esc(action)}" ${disabled?'disabled':''}>${esc(text)}</button>`;
function deadline(s,o){
 if(!Number.isSafeInteger(o.expires)||o.expires<0)return '<p class="muted">Échéance non précisée pour cette offre.</p>';
 const days=o.expires-s.day;
 return `<p class="offer-deadline">${days>0?`Échéance annoncée : dans ${days} jour${days>1?'s':''} de jeu`:'Échéance annoncée atteinte'} (jour ${o.expires}). La décision reste en pause, sans expiration automatique de cette offre.</p>`;
}
const club=(s,id)=>s.teams.find(t=>t.id===id)?.name||'Ancien club';
function amounts(terms,rate){const net=terms.salary*.76,fee=net*rate;return `<dl class="contract-amounts"><div><dt>Brut annuel</dt><dd>${money(terms.salary)}</dd></div><div><dt>Net avant commission</dt><dd>${money(net)}</dd></div><div><dt>Commission · ${rate*100} %</dt><dd>${money(fee)} / an</dd></div><div><dt>Net après commission</dt><dd>${money(net-fee)} / an</dd></div><div><dt>Durée</dt><dd>${esc(terms.years)} an(s)</dd></div><div><dt>Total théorique net</dt><dd>${money((net-fee)*terms.years)}</dd></div></dl>`;}
export function representationView(s){
 const r=s.representation,c=r?.contract,m=MANDATES[r?.mandate]||MANDATES.self,locked=!!(s.pending||s.match||s.retired);
 return `<section class="panel" id="agent-panel" tabindex="-1"><p class="eyebrow">VOTRE REPRÉSENTATION</p><h3>Mon agent</h3><p>Le mandat futur s’applique aux prochaines négociations. Le taux du contrat actuel reste fixé à la signature.</p><label>Mon mandat futur<select id="agent-mandate"${locked?' disabled':''}>${Object.values(MANDATES).map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${x.label} · ${x.rate*100} %</option>`).join('')}</select></label><p>${m.rate?`Sur 100 000 € nets reçus, coût estimé : ${money(100000*m.rate)}. Il faut environ ${(100*m.rate/(1-m.rate)).toFixed(2).replace('.',',')} % de salaire supplémentaire pour compenser ces frais.`:'Autogestion : aucun frais. Vous pouvez négocier vous-même.'} Aucun paiement pour choisir un mandat ; aucun résultat garanti.</p><p>Votre contrat actuel : <b>${c?esc(MANDATES[c.mandate].label)+' · '+c.rate*100+' %':'sans commission'}</b>.<br>Frais déjà prélevés sur ce contrat : ${money(c?.commission||0)} · cumul carrière : ${money(r?.totals.commission||0)}.</p><p class="muted">Les estimations annuelles supposent un salaire constant. Les frais réels sont arrondis et prélevés chaque jour sur le salaire net reçu, jamais sur les sponsors.</p>${locked?'<p class="data-note">Le mandat est verrouillé pendant une décision, un match ou après la retraite.</p>':''}<details><summary>Historique des négociations</summary>${r?.history.length?`<div class="timeline">${r.history.slice().reverse().map(e=>`<article><div><h4>${esc(club(s,e.team))} · ${esc(outcome(e.outcome))}</h4><p>Jour ${esc(e.day)} · ${money(e.salary)} brut/an · ${esc(e.years)} an(s) · frais ${money(e.commission)}</p></div></article>`).join('')}</div>`:'<p>Aucune négociation enregistrée.</p>'}</details></section>`;
}
export const offerViewId=(s,index)=>s.offers[index].id??'legacy-'+index;
export function contractNegotiationView(s,offerId,ui={}){
 const index=s.offers.findIndex((o,i)=>offerViewId(s,i)===offerId),o=s.offers[index];if(!o)return '';
 const session=s.representation?.session,e=session?.offers.find(x=>x.offerId===offerId),rate=e?.eligible?MANDATES[session.mandate].rate:0,c=offerComparison(s,o),active=ui.offerId===offerId,q=active?ui.quote:null,changed=e&&(e.current.salary!==e.initial.salary||e.current.years!==e.initial.years),signing=active?ui.signature:null;
 return `<article class="contract-card" id="contract-${index}" tabindex="-1"><p class="eyebrow">${esc(leagueDef(o.league).name)}</p><h3>${esc(club(s,o.team))}</h3><p>${esc(o.role)} · ${c.minutes.join('–')} min estimées : projection, sans garantie de temps de jeu.</p><p>Projet : <b>${esc(c.project)}</b> · huit meilleurs coéquipiers : ${c.strength} de général. Concurrence : rang estimé ${c.rank} au poste.</p><p class="muted">${c.rivals.map(p=>esc(p.name)+' ('+p.ovr+')').join(' · ')||'Aucun concurrent direct au poste.'} Système ${c.sameSystem?'similaire':'différent'} : ${c.retention} % de maîtrise conservée en changeant de club.</p>${deadline(s,o)}<h4>${o.academic?'Place au programme':'Offre initiale'}</h4>${amounts(e?.initial||o,rate)}${changed?`<h4>Proposition courante</h4>${amounts(e.current,rate)}`:''}<p class="muted">Montants estimés ; le total théorique ne garantit pas les revenus de toute la durée.</p>${e?.eligible?`<p><b>${2-e.attempts} tentative(s) restante(s)</b> · ${esc(MANDATES[session.mandate].label)}. L’offre initiale reste disponible.</p>`:'<p>Offre non négociable, sans commission : parcours amateur, draft ou proposition conservée d’une ancienne version.</p>'}${active&&ui.message?`<p role="status">${esc(outcome(ui.message))}</p>`:''}<div class="button-row">${button(o.academic?'Choisir ce programme':'Signer l’offre initiale','sign:'+index)}${changed?button('Signer la proposition courante','sign-current:'+index):''}${e?.eligible?button('Négocier','counter-open:'+index,e.attempts>=2):''}</div>${active&&(ui.open||q)&&e?.eligible?`<section class="counter-form" id="counter-form" tabindex="-1"><h4>Préparer une contre-offre</h4><label>Hausse par rapport à l’offre initiale<select id="counter-raise">${[0,5,10,15].map(n=>`<option value="${n}" ${(ui.raise??5)===n?'selected':''}>+${n} %</option>`).join('')}</select></label><label>Durée demandée<select id="counter-years">${[e.initial.years-1,e.initial.years,e.initial.years+1].filter(n=>n>=1&&n<=4).map(n=>`<option value="${n}" ${(ui.years??e.initial.years)===n?'selected':''}>${n} an(s)</option>`).join('')}</select></label><p>Une tentative est consommée uniquement après confirmation, même en cas de refus.</p>${q?`<div role="status"><h4>${esc(outcome(q.response.outcome))}</h4>${amounts(q.response,rate)}<ul>${q.response.reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>${button('Confirmer la contre-offre','counter-submit')}`:button('Examiner la réponse prévue','counter-preview')}${button('Annuler','counter-dismiss')}</section>`:''}${signing?`<section class="signature-confirm" id="signature-confirm" tabindex="-1"><h4>Confirmer la signature</h4><p>${esc(club(s,o.team))} · ${signing.source==='current'?'proposition courante':'offre initiale'}. Aucun frais immédiat.</p>${amounts(e?.[signing.source]||o,rate)}${button('Confirmer la signature','sign-confirm')}${button('Annuler','counter-dismiss')}</section>`:''}</article>`;
}
export function negotiationOffersView(s,ui={}){return `<label>Ma priorité<select id="market-preference">${Object.entries(PREFERENCES).map(([id,label])=>`<option value="${id}" ${id===s.careerPlan.preference?'selected':''}>${esc(label)}</option>`).join('')}</select></label><div class="offers comparison-offers">${orderedOffers(s).map(({index})=>contractNegotiationView(s,offerViewId(s,index),ui)).join('')}</div>`;}
